<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import AppHeader from '../components/AppHeader.vue'
import CharacterAttributePanel from '../components/CharacterAttributePanel.vue'
import { attributes, passiveTargets } from '../data/bramble'
import { skillDefinitions } from '../data/characterOptions'
import { loreSpells } from '../data/magicOptions'
import { loreDescriptions, spellDetails } from '../data/magicDetails'
import { ruleSourceDocuments } from '../data/rulesCurrent'
import { canonicalTalentName, talentNameMatches } from '../data/talentCategories'
import { CHARACTER_MAX_HEALTH, characterSheetArmorProfile, characterSheetWeaponProfile, derivedStats, equippedProtectiveGear, equipmentArmorPenalty, equipmentControlBonus, equipmentGutsBonus, equipmentMagicRegenBonus, equipmentManaSyphon, equipmentRenewHeartConditionBonus, equipmentSpellManaReduction, equipmentSpeedPenalty, equipmentWeightLb, healthCondition, magicResources, normalizeSkillName, rankModifier, rhythmResult, speciesMinimumSpeed, structuredRule, visibleRuleFields } from '../rules/rulesEngine'
import { applyScriptweaveCooldown, resolveSpellManaCost, spellCostBreakdownLabel } from '../rules/magicRules'
import { formatThreadpieceBalance } from '../rules/threadpieces'
import { characterStatus, characterWealthWp, loadCharacters, upsertCharacter, type CharacterRecord } from '../services/characters'
import { readLocalStorage, RHYTHM_STORE, writeLocalStorage } from '../services/storage'
import { loadCustomData, type CustomSpeciesItem, type CustomSpellItem, type CustomTalentItem } from '../services/customData'
import { adventureKitEquipment } from '../data/equipment'
import { abilityFeaturePillClass, abilityFeaturePillKeywords, abilityFeaturePillLabel, abilityTypeClass, abilityTypeKeywords, activeAbilityKeywords } from '../rules/abilityPresentation'
import { characterThreatBreakdown, characterThreatLevel } from '../rules/threatLevel'
import { externalMonsters } from '../data/externalMonsters'
import { copyEncounter, deleteEncounter, encounterCreationComplete, encounterStatus, loadEncounters, setEncounterApproval, setEncounterLocked, upsertEncounter, type EncounterRecord, type EncounterStatus } from '../services/encounters'
import { encounterEnvironmentOptions, encounterTrapOptions } from '../data/encounterOptions'

type RhythmMode='normal'|'edged'|'weighted'
type TargetMode='none'|'passive'|'active'
type RhythmResultValue=ReturnType<typeof rhythmResult>
interface RhythmHistoryEntry{id:string;createdAt:string;rollType:string;mode:RhythmMode;stat:number;skillName:string;skillBonus:number;conditions:number;target:number|null;targetLabel:string;result:RhythmResultValue;fortunes:number;misfortunes:number}
const sheet=ref<'attribute'|'character'|'encounter'>('attribute')
const characters=ref<CharacterRecord[]>(loadCharacters().filter(character=>characterStatus(character)!=='incomplete'))
const selectedCharacterId=ref(characters.value[0]?.id||'')
const selectedCharacter=computed(()=>selectedCharacterId.value?characters.value.find(character=>character.id===selectedCharacterId.value)||null:null)
const customData=loadCustomData()
const customSpecies=customData.filter((item):item is CustomSpeciesItem=>item.type==='species')
const customSpells=customData.filter((item):item is CustomSpellItem=>item.type==='spell')
const customTalents=customData.filter((item):item is CustomTalentItem=>item.type==='talent')
function isCustomSpecies(name:string){return customSpecies.some(item=>item.name===name)}
function isCustomSpell(name:string){return customSpells.some(item=>item.name===name)}
function isCustomTalent(name:string){return customTalents.some(item=>item.name===name)}

function die(){const a=new Uint32Array(1);crypto.getRandomValues(a);return(a[0]%10)+1}
function dice(count:number){return Array.from({length:count},die)}
function readStore<T>(key:string,fallback:T):T{try{return JSON.parse(readLocalStorage(key)||'') as T}catch{return fallback}}
function writeStore(key:string,value:unknown){return writeLocalStorage(key,JSON.stringify(value))}
function stamp(){return new Date().toISOString()}
function formatTime(value:string){return new Date(value).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})}
function rank(c:CharacterRecord,key:'agility'|'might'|'hide'|'lore'|'bravery'){return Number(c.attributes?.[key]||0)}
const skillModifier=rankModifier

const rollTypes=['Attribute Save','Compelled','Initiative','Other','Role-Play','Skill Check','Strike','Ward'] as const
const rollType=ref<(typeof rollTypes)[number]>('Attribute Save')
const rhythmMode=ref<RhythmMode>('normal')
const rhythmStat=ref(0),rhythmSkillBonus=ref(0),rhythmConditions=ref(0)
const rhythmSkill=ref('')
const targetMode=ref<TargetMode>('none'),passiveTarget=ref(18),activeTarget=ref<number|null>(null)
const rhythmHistory=ref<RhythmHistoryEntry[]>(readStore<RhythmHistoryEntry[]>(RHYTHM_STORE,[]).slice(0,5))
const characterStatKey=ref('agility')

const allCharacterStats=computed(()=>{
  const c=selectedCharacter.value;if(!c)return[] as Array<{key:string;label:string;value:number;attribute:string}>
  const secondary=derivedStats(c.attributes,equipmentGutsBonus(c.equipment),equipmentControlBonus(c.equipment),equipmentSpeedPenalty(c.equipment,c.species==='Tordan'),speciesMinimumSpeed(c.species))
  return[
    {key:'agility',label:'Agility',value:rankModifier(rank(c,'agility')),attribute:'Agility'},
    {key:'might',label:'Might',value:rankModifier(rank(c,'might')),attribute:'Might'},
    {key:'hide',label:'Hide',value:rankModifier(rank(c,'hide')),attribute:'Hide'},
    {key:'lore',label:'Lore',value:rankModifier(rank(c,'lore')),attribute:'Lore'},
    {key:'bravery',label:'Bravery',value:rankModifier(rank(c,'bravery')),attribute:'Bravery'},
    {key:'speed',label:'Speed',value:secondary.speed,attribute:'Agility'},
    {key:'aim',label:'Aim',value:secondary.aim,attribute:'Agility'},
    {key:'accuracy',label:'Accuracy',value:secondary.accuracy,attribute:'Agility'},
    {key:'brawl',label:'Brawl',value:secondary.brawl,attribute:'Might'},
    {key:'fury',label:'Fury',value:secondary.fury,attribute:'Might'},
    {key:'ward',label:'Ward',value:secondary.ward,attribute:'Hide'},
    {key:'guts',label:'Guts',value:secondary.guts,attribute:'Hide'},
    {key:'control',label:'Control',value:secondary.control,attribute:'Lore'},
    {key:'power',label:'Power',value:secondary.power,attribute:'Lore'},
    {key:'spirit',label:'Spirit',value:secondary.spirit,attribute:'Bravery'},
    {key:'heart',label:'Heart',value:secondary.heart,attribute:'Bravery'},
  ]
})
function allowedStatKeys(type:string){
  if(type==='Initiative')return['speed']
  if(type==='Strike')return['aim','brawl','control']
  if(type==='Ward')return['ward']
  if(['Attribute Save','Compelled','Skill Check','Role-Play'].includes(type))return['agility','might','hide','lore','bravery']
  return allCharacterStats.value.map(item=>item.key)
}
const statOptions=computed(()=>{const allowed=new Set(allowedStatKeys(rollType.value));return allCharacterStats.value.filter(item=>allowed.has(item.key))})
const selectedStat=computed(()=>statOptions.value.find(item=>item.key===characterStatKey.value)||statOptions.value[0]||null)
function statOptionLabel(stat:{key:string;label:string;value:number}){
  if(stat.key==='aim')return`Aim +${stat.value} (Shooting)`
  if(stat.key==='brawl')return`Brawl +${stat.value} (Melee)`
  if(stat.key==='control')return`Control +${stat.value} (Magic)`
  return`${stat.label} +${stat.value}`
}
const rollUsesSkill=computed(()=>['Skill Check','Role-Play','Other'].includes(rollType.value))
const characterSkillOptions=computed(()=>{
  const c=selectedCharacter.value,stat=selectedStat.value;if(!c||!stat||!rollUsesSkill.value)return[] as Array<{name:string;rank:number}>
  return Object.entries(c.skillRanks||{}).map(([name,value])=>({name:normalizeSkillName(name),rank:Number(value)})).filter(entry=>{
    const def=skillDefinitions.find(item=>normalizeSkillName(item.name)===entry.name)
    return Boolean(def)&&def?.attribute===stat.attribute
  }).sort((a,b)=>a.name.localeCompare(b.name))
})
const statFieldLabel=computed(()=>rollType.value==='Strike'?'Strike Stat':rollType.value==='Ward'?'Ward Stat':rollType.value==='Initiative'?'Initiative Stat':rollType.value==='Attribute Save'?'Save Attribute':rollType.value==='Skill Check'?'Skill Attribute':'Character Stat')
const skillFieldLabel=computed(()=>selectedStat.value?`${selectedStat.value.attribute} Skill`:'Character Skill')
watch([rollType,selectedCharacterId],()=>{const first=statOptions.value[0];characterStatKey.value=first?.key||'agility';rhythmSkill.value='';if(!rollUsesSkill.value)rhythmSkillBonus.value=0},{immediate:true})
watch(characterStatKey,()=>{rhythmSkill.value='';if(selectedCharacter.value)rhythmStat.value=selectedStat.value?.value||0},{immediate:true})
watch(rhythmSkill,()=>{if(!rollUsesSkill.value){rhythmSkillBonus.value=0;return}if(selectedCharacter.value){const entry=characterSkillOptions.value.find(item=>item.name===rhythmSkill.value);rhythmSkillBonus.value=skillModifier(entry?.rank||0)}})
const effectiveRhythmStat=computed(()=>selectedCharacter.value?Number(selectedStat.value?.value||0):Number(rhythmStat.value||0))
const rhythmCombinedStat=computed(()=>effectiveRhythmStat.value+(rollUsesSkill.value?Number(rhythmSkillBonus.value||0):0))
const gearRenewHeartBonus=computed(()=>equipmentRenewHeartConditionBonus(selectedCharacter.value?.equipment))
const selectedHealthState=computed(()=>healthCondition(selectedCharacter.value?.currentHealth??CHARACTER_MAX_HEALTH))
const effectiveRhythmConditions=computed(()=>Number(rhythmConditions.value||0)+(rollType.value==='Compelled'?gearRenewHeartBonus.value:0)+(normalizeSkillName(rhythmSkill.value)==='Whisperster'?gearArmorPenalty.value:0)+selectedHealthState.value.condition)
const rollSummary=computed(()=>{const style=rhythmMode.value==='normal'?'Normal':rhythmMode.value==='edged'?'Edged':'Weighted';const stat=selectedStat.value?.label||statFieldLabel.value;const parts=[`${stat} (${effectiveRhythmStat.value})`];if(rollUsesSkill.value&&rhythmSkill.value)parts.push(`${rhythmSkill.value} (${Number(rhythmSkillBonus.value||0)})`);const conditions=effectiveRhythmConditions.value;if(conditions!==0)parts.push(`Conditions (${conditions})`);if(rollType.value==='Compelled'&&gearRenewHeartBonus.value)parts.push(`Votive Icon (+${gearRenewHeartBonus.value})`);if(selectedHealthState.value.condition)parts.push(`${selectedHealthState.value.label} (${selectedHealthState.value.condition})`);return`${style} ${rollType.value} Roll: ${parts.join(' + ')} = ${rhythmCombinedStat.value+conditions}`})
const currentTarget=computed(()=>targetMode.value==='passive'?Number(passiveTarget.value):targetMode.value==='active'&&activeTarget.value!==null?Number(activeTarget.value):null)
function targetLabel(){if(targetMode.value==='active')return'Active Target';if(targetMode.value==='passive')return passiveTargets.find(([,value])=>value===Number(passiveTarget.value))?.[0]||'Passive Target';return'No Target'}
function rollAttributeCheck(){const conditions=effectiveRhythmConditions.value;const result=rhythmResult(dice(rhythmMode.value==='normal'?3:4),rhythmMode.value,rhythmCombinedStat.value,conditions);const kept=result.kept||result.rolled;const entry:RhythmHistoryEntry={id:crypto.randomUUID(),createdAt:stamp(),rollType:rollType.value,mode:rhythmMode.value,stat:effectiveRhythmStat.value,skillName:rollUsesSkill.value?rhythmSkill.value:'',skillBonus:rollUsesSkill.value?Number(rhythmSkillBonus.value||0):0,conditions,target:currentTarget.value,targetLabel:targetLabel(),result,fortunes:kept.filter(value=>value>=8).length,misfortunes:kept.filter(value=>value<=2).length};rhythmHistory.value=[entry,...rhythmHistory.value].slice(0,5);const saved=writeStore(RHYTHM_STORE,rhythmHistory.value);if(!saved.ok)alert(saved.message)}
function rollOutcome(entry:RhythmHistoryEntry){if(entry.target===null)return'';return entry.result.total>=entry.target?'SUCCESS':'FAILURE'}

const gearGutsBonus=computed(()=>equipmentGutsBonus(selectedCharacter.value?.equipment))
const gearControlBonus=computed(()=>equipmentControlBonus(selectedCharacter.value?.equipment))
const gearMagicRegenBonus=computed(()=>equipmentMagicRegenBonus(selectedCharacter.value?.equipment))
const gearArmorPenalty=computed(()=>equipmentArmorPenalty(selectedCharacter.value?.equipment))
const gearSpeedPenalty=computed(()=>equipmentSpeedPenalty(selectedCharacter.value?.equipment,selectedCharacter.value?.species==='Tordan'))
const minimumSpeed=computed(()=>speciesMinimumSpeed(selectedCharacter.value?.species))
const secondaryStats=computed(()=>selectedCharacter.value?derivedStats(selectedCharacter.value.attributes,gearGutsBonus.value,gearControlBonus.value,gearSpeedPenalty.value,minimumSpeed.value):null)
const selectedSkills=computed(()=>{const c=selectedCharacter.value;if(!c)return[];const ranks=c.skillRanks&&Object.keys(c.skillRanks).length?c.skillRanks:Object.fromEntries((c.skills||[]).map(name=>[normalizeSkillName(name),1]));return Object.entries(ranks).map(([name,value])=>({name:normalizeSkillName(name),rank:Number(value)})).sort((a,b)=>a.name.localeCompare(b.name))})
const weapons=computed(()=>selectedCharacter.value?.equipment?.filter(item=>item.category==='Weapon')||[])
const armor=computed(()=>equippedProtectiveGear(selectedCharacter.value?.equipment))
const allOwnedEquipment=computed(()=>selectedCharacter.value?[...adventureKitEquipment(selectedCharacter.value.adventureKit),...(selectedCharacter.value.equipment||[])]:[])
const otherGear=computed(()=>allOwnedEquipment.value.filter(item=>!['Weapon','Armor & Shield','Trinket'].includes(item.category||'')))
const ownedItemCount=computed(()=>allOwnedEquipment.value.reduce((sum,item)=>sum+Math.max(1,Math.floor(Number(item.quantity)||1)),0))
const ownedEquipmentWeight=computed(()=>allOwnedEquipment.value.reduce((sum,item)=>sum+equipmentWeightLb(item),0))
function gearWeightLabel(item:{weightLb?:number;detail?:string;quantity?:number}){const weight=equipmentWeightLb(item);return weight?`${Number.isInteger(weight)?weight:weight.toFixed(1)} lb.`:'Weight —'}
const equipmentWeightLabel=computed(()=>{const value=ownedEquipmentWeight.value;return`${Number.isInteger(value)?value:value.toFixed(1)} lb.`})
const equipmentWealthLabel=computed(()=>selectedCharacter.value?formatThreadpieceBalance(characterWealthWp(selectedCharacter.value)):'—')
const weaponSlots=computed(()=>Array.from({length:Math.max(3,weapons.value.length)},(_,index)=>characterSheetWeaponProfile(weapons.value[index],selectedCharacter.value?.equipment)))
const armorSlots=computed(()=>Array.from({length:Math.max(2,armor.value.length)},(_,index)=>characterSheetArmorProfile(armor.value[index],selectedCharacter.value?.equipment)))
const equippedTrinkets=computed(()=>selectedCharacter.value?.equipment?.filter(item=>item.category==='Trinket'&&(item.equipped!==false))||[])
function skillToneClass(name:string){const def=skillDefinitions.find(item=>normalizeSkillName(item.name)===normalizeSkillName(name));return def?`skill-tone-${def.attribute.toLowerCase()}`:''}
function setCharacterHealth(value:number){const c=selectedCharacter.value;if(!c)return;const currentHealth=Math.max(0,Math.min(CHARACTER_MAX_HEALTH,Math.round(Number(value)||0)));const updated={...c,currentHealth,updatedAt:stamp()};const result=upsertCharacter(updated);if(!result.ok)return;characters.value=loadCharacters().filter(character=>characterStatus(character)!=='incomplete');selectedCharacterId.value=updated.id}

function spellDetail(name:string){const custom=customSpells.find(item=>item.name===name);return custom||spellDetails[name]}
const talentSections=ruleSourceDocuments.talents.sections
function talentText(name:string){const custom=customTalents.find(item=>item.name===name);if(custom)return custom.text;const section=talentSections.find(item=>talentNameMatches(item.heading,name));return section?.blocks.filter(block=>block.type==='paragraph').map(block=>block.type==='paragraph'?block.text:'').join(' ')||''}
function talentKeywords(name:string){const custom=customTalents.find(item=>item.name===name);if(custom)return activeAbilityKeywords(custom.keywords);const match=talentText(name).match(/\bKEYWORDS?:\s*(.+)$/i);return activeAbilityKeywords(match?[match[1]]:[])}
function talentAbilityTypes(name:string){return abilityTypeKeywords(talentKeywords(name))}
function talentAbilityClasses(name:string){return talentAbilityTypes(name).map(abilityTypeClass)}
function weaponPropertyPills(value:string){return value==='—'?[]:String(value||'').split(',').map(part=>part.trim()).filter(Boolean)}
function spellLoreClass(name:string){return `spell-lore-${String(spellDetail(name)?.lore||'invocation').toLowerCase()}`}
const magicLevel=computed(()=>Number(selectedCharacter.value?.magicLevel??(selectedCharacter.value?.path==='magic'?1:0)))
const resources=computed(()=>selectedCharacter.value?magicResources(selectedCharacter.value.attributes,magicLevel.value,gearMagicRegenBonus.value):{manaPool:0,magicRegen:0})
const maxMana=computed(()=>resources.value.manaPool)
const signatureSpell=computed(()=>{const c=selectedCharacter.value;if(!c?.loreAttunement)return'';return customSpells.find(item=>item.lore===c.loreAttunement&&item.signature)?.name||loreSpells[c.loreAttunement]?.[0]||''})
function spellNamesForCharacter(character:CharacterRecord|null){if(!character)return[] as string[];const level=Math.max(0,Number(character.magicLevel??(character.path==='magic'?1:0))||0);if(level<1)return[] as string[];const signature=character.loreAttunement?(customSpells.find(item=>item.lore===character.loreAttunement&&item.signature)?.name||loreSpells[character.loreAttunement]?.[0]||''):'';return Array.from(new Set([signature,...(character.spells||[]),...(character.invocationSpells||[]),...(character.invocationSpell?[character.invocationSpell]:[])].filter(Boolean) as string[]))}
const characterSpells=computed(()=>spellNamesForCharacter(selectedCharacter.value))
function effectiveMana(name:string){
  const detail=spellDetail(name);if(!detail)return null
  const custom=customSpells.find(item=>item.name===name)
  return resolveSpellManaCost({name,lore:detail.lore,baseCost:detail.manaCost,attunedLore:selectedCharacter.value?.loreAttunement,manaSyphon:equipmentManaSyphon(selectedCharacter.value?.equipment),focusReduction:equipmentSpellManaReduction(selectedCharacter.value?.equipment,name),signature:Boolean(custom?.signature),cantrip:Boolean(custom&&!custom.signature&&detail.lore==='Invocation'&&detail.manaCost===0)})
}
function spellCostText(name:string){
  const detail=spellDetail(name);if(!detail)return'Variable'
  const custom=customSpells.find(item=>item.name===name)
  return spellCostBreakdownLabel({name,lore:detail.lore,baseCost:detail.manaCost,attunedLore:selectedCharacter.value?.loreAttunement,manaSyphon:equipmentManaSyphon(selectedCharacter.value?.equipment),focusReduction:equipmentSpellManaReduction(selectedCharacter.value?.equipment,name),signature:Boolean(custom?.signature),cantrip:Boolean(custom&&!custom.signature&&detail.lore==='Invocation'&&detail.manaCost===0)})
}
function spellRulesForCharacter(name:string){const rules=spellDetail(name)?.rules||'';return applyScriptweaveCooldown(rules,equipmentSpellManaReduction(selectedCharacter.value?.equipment,name)>0)}
const loreCharacterSpells=computed(()=>characterSpells.value.filter(name=>!selectedCharacter.value?.invocationSpells?.includes(name)&&name!==selectedCharacter.value?.invocationSpell).sort((a,b)=>(effectiveMana(a)??999)-(effectiveMana(b)??999)||a.localeCompare(b)))
const invocationCharacterSpells=computed(()=>characterSpells.value.filter(name=>selectedCharacter.value?.invocationSpells?.includes(name)||name===selectedCharacter.value?.invocationSpell).sort((a,b)=>(effectiveMana(a)??999)-(effectiveMana(b)??999)||a.localeCompare(b)))
const selectedPathName=computed(()=>({magic:'Wind-Touched',talents:'Gifted Heart',skills:'Practiced Hand',attribute:'Tempered Form'} as const)[selectedCharacter.value?.path||'magic']||'Gifted Heart')
const selectedThreat=computed(()=>{const character=selectedCharacter.value;if(!character)return null;return characterThreatBreakdown({attributeRanks:attributes.map(attribute=>Number(character.attributes?.[attribute.id]||1)),skillRanks:Object.values(character.skillRanks||{}).map(Number),talentCount:(character.talents||[]).filter(Boolean).length,magicLevel:magicLevel.value})})
const selectedThreatLevel=computed(()=>selectedThreat.value?.level||1)

const encounterSteps=['Details','Party','Opposition','Battlefield','Review'] as const
type EncounterStep=(typeof encounterSteps)[number]
const encounterStep=ref<EncounterStep>('Details')
const encounters=ref<EncounterRecord[]>(loadEncounters())
const encounterSaveMessage=ref('')
const opponentName=ref('')
const opponentQuantity=ref(1)
function encounterId(){return typeof crypto!=='undefined'&&'randomUUID' in crypto?crypto.randomUUID():`encounter-${Date.now()}-${Math.random().toString(36).slice(2,8)}`}
function blankEncounter():EncounterRecord{const now=stamp();return{id:encounterId(),name:'',objective:'',partyCharacterIds:[],opponents:[],traps:[],environments:[],environment:'',notes:'',status:'incomplete',creationComplete:false,locked:false,createdAt:now,updatedAt:now}}
const encounterDraft=reactive<EncounterRecord>(blankEncounter())
const encounterMonsterOptions=computed(()=>externalMonsters.filter(monster=>monster.category!=='Companions').slice().sort((a,b)=>a.category.localeCompare(b.category)||a.name.localeCompare(b.name)))
function threatForCharacter(character:CharacterRecord){return characterThreatLevel({attributeRanks:attributes.map(attribute=>Number(character.attributes?.[attribute.id]||1)),skillRanks:Object.values(character.skillRanks||{}).map(Number),talentCount:(character.talents||[]).filter(Boolean).length,magicLevel:Number(character.magicLevel||0)})}
const encounterParty=computed(()=>characters.value.filter(character=>encounterDraft.partyCharacterIds.includes(character.id)))
const encounterGroupThreat=computed(()=>encounterParty.value.reduce((sum,character)=>sum+threatForCharacter(character),0))
const encounterOpponentTotal=computed(()=>encounterDraft.opponents.reduce((sum,item)=>sum+item.quantity,0))
const encounterGroups=computed(()=>{const statuses:EncounterStatus[]=['approved','unapproved','incomplete'];return statuses.map(status=>({status,label:status==='approved'?'Approved Encounters':status==='unapproved'?'Unapproved Encounters':'Incomplete Encounters',items:encounters.value.filter(item=>encounterStatus(item)===status)}))})
function setEncounterStep(step:EncounterStep){encounterStep.value=step}
function newEncounter(){Object.assign(encounterDraft,blankEncounter());encounterStep.value='Details';encounterSaveMessage.value=''}
function editEncounter(encounter:EncounterRecord){if(encounter.locked){encounterSaveMessage.value='Unlock this encounter before editing it.';return}Object.assign(encounterDraft,JSON.parse(JSON.stringify(encounter)));encounterStep.value='Details';encounterSaveMessage.value=''}
function toggleEncounterParty(id:string,checked:boolean){encounterDraft.partyCharacterIds=checked?Array.from(new Set([...encounterDraft.partyCharacterIds,id])):encounterDraft.partyCharacterIds.filter(value=>value!==id)}
function toggleEncounterOption(kind:'traps'|'environments',value:string,checked:boolean){const current=encounterDraft[kind];encounterDraft[kind]=checked?Array.from(new Set([...current,value])):current.filter(item=>item!==value)}
function addEncounterOpponent(){const name=opponentName.value.trim();if(!name)return;const quantity=Math.max(1,Math.floor(Number(opponentQuantity.value)||1));const existing=encounterDraft.opponents.find(item=>item.name===name);if(existing)existing.quantity+=quantity;else encounterDraft.opponents.push({name,quantity});opponentName.value='';opponentQuantity.value=1}
function removeEncounterOpponent(index:number){encounterDraft.opponents.splice(index,1)}
function saveEncounterRecord(complete:boolean){if(complete&&(!encounterDraft.name.trim()||!encounterDraft.objective.trim()||!encounterDraft.opponents.length)){encounterSaveMessage.value='Add an encounter name, objective, and at least one opponent before finishing it.';return}const now=stamp();if(!encounterDraft.createdAt)encounterDraft.createdAt=now;encounterDraft.updatedAt=now;const candidate={...encounterDraft,name:encounterDraft.name.trim()||'Untitled Encounter',creationComplete:complete,status:complete?(encounterDraft.status==='approved'?'approved':'unapproved'):'incomplete'} as EncounterRecord;if(complete&&!encounterCreationComplete({...candidate,creationComplete:undefined,status:undefined})){encounterSaveMessage.value='Add an encounter name, objective, and at least one opponent before finishing it.';return}const saved=upsertEncounter(encounters.value,candidate);if(saved.result.ok){encounters.value=saved.encounters;Object.assign(encounterDraft,saved.encounters.find(item=>item.id===candidate.id)||candidate);encounterSaveMessage.value=complete?'Encounter finished and ready for approval.':'Encounter draft saved.'}else encounterSaveMessage.value=saved.result.message}
function saveEncounterDraft(){saveEncounterRecord(false)}
function finishEncounterDraft(){saveEncounterRecord(true)}
function updateEncounterApproval(encounter:EncounterRecord,approved:boolean){const result=setEncounterApproval(encounters.value,encounter.id,approved);if(result.result.ok)encounters.value=result.encounters;encounterSaveMessage.value=result.result.message||''}
function updateEncounterLock(encounter:EncounterRecord,locked:boolean){const result=setEncounterLocked(encounters.value,encounter.id,locked);if(result.result.ok)encounters.value=result.encounters;encounterSaveMessage.value=result.result.message||''}
function duplicateEncounter(encounter:EncounterRecord){const result=copyEncounter(encounters.value,encounter.id,encounterId());if(result.result.ok)encounters.value=result.encounters;encounterSaveMessage.value=result.result.ok?'Encounter copied.':result.result.message}
function removeSavedEncounter(encounter:EncounterRecord){if(encounter.locked){encounterSaveMessage.value='Unlock this encounter before deleting it.';return}if(encounter.status==='approved'){encounterSaveMessage.value='Remove approval before deleting this encounter.';return}if(typeof window!=='undefined'&&!window.confirm('Delete this saved encounter?'))return;const deleted=deleteEncounter(encounters.value,encounter.id);if(deleted.result.ok){encounters.value=deleted.encounters;if(encounterDraft.id===encounter.id)newEncounter();encounterSaveMessage.value='Encounter deleted.'}else encounterSaveMessage.value=deleted.result.message}

</script>

<template>
  <main class="page simulator-page rhythm-engine-page">
    <AppHeader />
    <div class="page-title-block"><h1>Rhythm Engine</h1></div>
    <div class="segment-tabs simulator-tabs rhythm-sheet-tabs"><button type="button" class="segment-tab" :class="{active:sheet==='character'}" @click="sheet='character'">Character Sheet</button><button type="button" class="segment-tab" :class="{active:sheet==='attribute'}" @click="sheet='attribute'">Dice Roller</button><button type="button" class="segment-tab" :class="{active:sheet==='encounter'}" @click="sheet='encounter'">Encounter Builder</button></div>

    <section v-if="sheet!=='encounter'" class="character-selection-panel card-surface"><label class="field-label">Character<select v-model="selectedCharacterId" class="field-control"><option value="">Manual / No Character</option><option v-for="character in characters" :key="character.id" :value="character.id">{{ character.name }} {{ character.species }}</option></select></label><div v-if="selectedCharacter" class="character-selection-summary"><strong>{{ selectedCharacter.name }}</strong><span>{{ selectedCharacter.species }} · {{ selectedCharacter.campaignName||'No Campaign' }}</span></div></section>

    <section v-if="sheet==='attribute'" class="tool-panel card-surface rhythm-tool-card">
      <div class="tool-heading"><div><p class="eyebrow">DICE ROLLER</p><h2>3d10 + Stat + Skill</h2></div></div>
      <p class="tool-explainer">Choose a Roll Type, then the valid Character Stat. Skills only turn on for roll types that use a Skill.</p>
      <aside class="fortune-tip"><strong>Fortune &amp; Misfortune</strong><span>Natural dice of 8–10 create Fortune results and natural dice of 1–2 create Misfortune results. Fortune represents an advantageous twist and may create a +1 Condition where the rule allows; Misfortune represents a complication and may create a −1 Condition.</span></aside>
      <div class="rhythm-dependent-grid"><label class="field-label">Roll Type<select v-model="rollType" class="field-control"><option v-for="option in rollTypes" :key="option">{{ option }}</option></select></label><label class="field-label">{{ statFieldLabel }}<select v-if="selectedCharacter" v-model="characterStatKey" class="field-control"><option v-for="stat in statOptions" :key="stat.key" :value="stat.key">{{ statOptionLabel(stat) }}</option></select><input v-else v-model.number="rhythmStat" class="field-control" type="number" /></label><label class="field-label" :class="{'field-off':!rollUsesSkill}">{{ rollUsesSkill?skillFieldLabel:'Skill (Off)' }}<select v-if="rollUsesSkill&&selectedCharacter" v-model="rhythmSkill" class="field-control"><option value="">No Skill</option><option v-for="skill in characterSkillOptions" :key="skill.name" :value="skill.name">{{ skill.name }} Rank {{ skill.rank }} +{{ skillModifier(skill.rank) }}</option></select><input v-else-if="rollUsesSkill" v-model.number="rhythmSkillBonus" class="field-control" type="number" placeholder="Skill Bonus" /><div v-else class="field-control disabled-readout">Off</div></label></div>
      <div class="rhythm-target-row"><label class="field-label rhythm-style-field">Roll Style<select v-model="rhythmMode" class="field-control"><option value="normal">Normal 3d10</option><option value="edged">Edged 4d10, Drop Lowest</option><option value="weighted">Weighted 4d10, Drop Highest</option></select></label><label class="field-label conditions-short-field">Conditions<input v-model.number="rhythmConditions" class="field-control" type="number" /></label><label class="field-label target-type-field">Target Type<select v-model="targetMode" class="field-control"><option value="none">No Target</option><option value="passive">Passive</option><option value="active">Active</option></select></label><label v-if="targetMode==='passive'" class="field-label target-value-field">Passive Target<select v-model.number="passiveTarget" class="field-control"><option v-for="target in passiveTargets" :key="target[0]" :value="target[1]">{{ target[0] }} {{ target[1] }}</option></select></label><label v-else-if="targetMode==='active'" class="field-label target-value-field">Active Target<input v-model.number="activeTarget" class="field-control" type="number" min="0" placeholder="Enter Target" /></label></div>
      <div class="roll-formula-summary"><strong>{{ rollSummary }}</strong></div><button class="primary-button wide" @click="rollAttributeCheck">Roll {{ rollType }}</button>
      <div class="sim-history-heading"><div><strong>Recent Rolls</strong><small>The latest five rolls are kept on this device.</small></div></div><div v-if="rhythmHistory.length" class="rhythm-history-list"><article v-for="(entry,index) in rhythmHistory" :key="entry.id" class="result-panel rhythm-history-entry" :class="{latest:index===0}"><div class="result-meta"><span>{{ formatTime(entry.createdAt) }}</span><span>{{ entry.rollType }}</span><span>{{ entry.mode }}</span><span v-if="entry.target!==null">{{ entry.targetLabel }} {{ entry.target }}</span></div><div class="dice-row"><span v-for="(value,dieIndex) in entry.result.rolled" :key="dieIndex" class="die" :class="{fortune:value>=8,misfortune:value<=2}">{{ value }}</span></div><div class="result-summary"><strong class="result-total">{{ entry.result.total }}</strong><span v-if="entry.target!==null" class="outcome" :class="entry.result.total>=entry.target?'pass':'fail'">{{ rollOutcome(entry) }}</span></div><div v-if="entry.fortunes||entry.misfortunes" class="special-result-row"><span v-if="entry.fortunes" class="special-result fortune-result">Fortune ×{{ entry.fortunes }}</span><span v-if="entry.misfortunes" class="special-result misfortune-result">Misfortune ×{{ entry.misfortunes }}</span></div><small>{{ entry.result.natural }} natural + {{ entry.stat }} Stat<template v-if="entry.skillName"> + {{ entry.skillBonus }} {{ entry.skillName }}</template> {{ entry.conditions>=0?'+':'−' }} {{ Math.abs(entry.conditions) }} Conditions</small></article></div><div v-else class="empty-inline sim-empty-inline">No rolls yet.</div>
    </section>

    <section v-else-if="sheet==='encounter'" class="encounter-builder-shell">
      <section class="encounter-builder-heading card-surface"><div><p class="eyebrow">ENCOUNTER BUILDER</p><h2>{{ encounterDraft.name||'New Encounter' }}</h2><p>Build a reusable encounter from the current character roster and Watcher creature catalog.</p></div><button type="button" class="secondary-button" @click="newEncounter">New Encounter</button></section>
      <div class="segment-tabs encounter-step-tabs" role="tablist" aria-label="Encounter creation steps"><button v-for="step in encounterSteps" :key="step" type="button" class="segment-tab" :class="{active:encounterStep===step}" @click="setEncounterStep(step)">{{ step }}</button></div>
      <section v-if="encounterStep==='Details'" class="tool-panel card-surface encounter-step-panel"><div class="tool-heading"><div><p class="eyebrow">STEP 1</p><h2>Encounter Details</h2></div></div><div class="field-grid two"><label class="field-label">Encounter Name<input v-model="encounterDraft.name" class="field-control" placeholder="Beneath the Rootbridge" /></label><label class="field-label">Objective<input v-model="encounterDraft.objective" class="field-control" placeholder="Protect the crossing, recover a relic, escape…" /></label></div><div class="encounter-step-actions"><button type="button" class="primary-button" @click="setEncounterStep('Party')">Next: Party</button></div></section>
      <section v-else-if="encounterStep==='Party'" class="tool-panel card-surface encounter-step-panel"><div class="tool-heading"><div><p class="eyebrow">STEP 2</p><h2>Party</h2></div><strong>Group Threat {{ encounterGroupThreat }}</strong></div><p>Select the saved heroes taking part in this encounter.</p><div class="encounter-choice-grid"><label v-for="character in characters" :key="character.id" class="encounter-choice-card"><input type="checkbox" :checked="encounterDraft.partyCharacterIds.includes(character.id)" @change="toggleEncounterParty(character.id,($event.target as HTMLInputElement).checked)" /><span><strong>{{ character.name }}</strong><small>{{ character.species }} · TL {{ threatForCharacter(character) }}</small></span></label></div><p v-if="!characters.length" class="muted">No complete saved characters are available yet.</p><div class="encounter-step-actions"><button type="button" class="secondary-button" @click="setEncounterStep('Details')">Back</button><button type="button" class="primary-button" @click="setEncounterStep('Opposition')">Next: Opposition</button></div></section>
      <section v-else-if="encounterStep==='Opposition'" class="tool-panel card-surface encounter-step-panel"><div class="tool-heading"><div><p class="eyebrow">STEP 3</p><h2>Opposition</h2></div><strong>{{ encounterOpponentTotal }} creatures</strong></div><div class="encounter-opponent-add"><label class="field-label">Creature<select v-model="opponentName" class="field-control"><option value="">Select Creature</option><optgroup v-for="category in Array.from(new Set(encounterMonsterOptions.map(monster=>monster.category)))" :key="category" :label="category"><option v-for="monster in encounterMonsterOptions.filter(item=>item.category===category)" :key="monster.name" :value="monster.name">{{ monster.name }}{{ monster.placeholder?' — Placeholder':'' }}</option></optgroup></select></label><label class="field-label">Quantity<input v-model.number="opponentQuantity" class="field-control" type="number" min="1" /></label><button type="button" class="primary-button" :disabled="!opponentName" @click="addEncounterOpponent">Add</button></div><div v-if="encounterDraft.opponents.length" class="encounter-opponent-list"><article v-for="(opponent,index) in encounterDraft.opponents" :key="`${opponent.name}-${index}`"><div><strong>{{ opponent.name }}</strong><small>Quantity {{ opponent.quantity }}</small></div><button type="button" class="secondary-button compact-action" @click="removeEncounterOpponent(index)">Remove</button></article></div><p v-else class="muted">No opposition selected.</p><div class="encounter-step-actions"><button type="button" class="secondary-button" @click="setEncounterStep('Party')">Back</button><button type="button" class="primary-button" @click="setEncounterStep('Battlefield')">Next: Battlefield</button></div></section>
      <section v-else-if="encounterStep==='Battlefield'" class="tool-panel card-surface encounter-step-panel"><div class="tool-heading"><div><p class="eyebrow">STEP 4</p><h2>Battlefield</h2></div></div><div class="encounter-battlefield-groups"><fieldset><legend>Environments</legend><div class="encounter-choice-grid"><label v-for="option in encounterEnvironmentOptions" :key="option" class="encounter-choice-card"><input type="checkbox" :checked="encounterDraft.environments.includes(option)" @change="toggleEncounterOption('environments',option,($event.target as HTMLInputElement).checked)" /><span><strong>{{ option }}</strong><small>Environment option</small></span></label></div></fieldset><fieldset><legend>Traps</legend><div class="encounter-choice-grid"><label v-for="option in encounterTrapOptions" :key="option" class="encounter-choice-card"><input type="checkbox" :checked="encounterDraft.traps.includes(option)" @change="toggleEncounterOption('traps',option,($event.target as HTMLInputElement).checked)" /><span><strong>{{ option }}</strong><small>Trap option</small></span></label></div></fieldset></div><label class="field-label">Battlefield Notes<textarea v-model="encounterDraft.environment" class="field-control encounter-textarea" rows="4" placeholder="Terrain, hazards, light, elevation, cover, starting positions…"></textarea></label><label class="field-label">Watcher Notes<textarea v-model="encounterDraft.notes" class="field-control encounter-textarea" rows="5" placeholder="Triggers, reinforcements, special rules, rewards, or reminders…"></textarea></label><div class="encounter-step-actions"><button type="button" class="secondary-button" @click="setEncounterStep('Opposition')">Back</button><button type="button" class="primary-button" @click="setEncounterStep('Review')">Next: Review</button></div></section>
      <section v-else class="tool-panel card-surface encounter-step-panel encounter-review-panel"><div class="tool-heading"><div><p class="eyebrow">STEP 5</p><h2>Review Encounter</h2></div><span class="status-pill" :class="`status-${encounterStatus(encounterDraft)}`">{{ encounterStatus(encounterDraft) }}</span></div><div class="review-grid review-summary-grid encounter-review-grid"><article><span>Name</span><strong>{{ encounterDraft.name||'Untitled Encounter' }}</strong><small>{{ encounterDraft.objective||'No objective recorded' }}</small></article><article><span>Party</span><strong>{{ encounterParty.length }} characters</strong><small>Group Threat {{ encounterGroupThreat }}</small></article><article><span>Opposition</span><strong>{{ encounterOpponentTotal }} creatures</strong><small>{{ encounterDraft.opponents.map(item=>`${item.quantity}× ${item.name}`).join(' · ')||'None selected' }}</small></article><article><span>Battlefield</span><strong>{{ encounterDraft.environments.length||encounterDraft.traps.length||encounterDraft.environment?'Prepared':'Open' }}</strong><small>{{ [...encounterDraft.environments,...encounterDraft.traps].join(' · ')||encounterDraft.environment||'No battlefield options selected' }}</small></article></div><div class="encounter-step-actions"><button type="button" class="secondary-button" @click="setEncounterStep('Battlefield')">Back</button><button type="button" class="secondary-button" @click="saveEncounterDraft">Save Draft</button><button type="button" class="primary-button" @click="finishEncounterDraft">Finish for Approval</button></div><p v-if="encounterSaveMessage" class="encounter-save-message">{{ encounterSaveMessage }}</p></section>
      <section class="saved-encounters card-surface"><header><div><p class="eyebrow">SAVED</p><h2>Encounter List</h2></div><span>{{ encounters.length }}</span></header><div v-if="encounters.length" class="saved-encounter-groups"><details v-for="group in encounterGroups" :key="group.status" class="character-list-group" :class="`character-list-group-${group.status==='approved'?'approved':group.status==='unapproved'?'complete':'incomplete'}`" :open="group.items.length>0"><summary class="character-list-group-heading"><span><strong>{{ group.label }}</strong><small>{{ group.items.length }} encounters</small></span><span class="character-group-chevron" aria-hidden="true">⌄</span></summary><div class="character-list-group-body"><div v-if="group.items.length" class="saved-encounter-list"><article v-for="encounter in group.items" :key="encounter.id" :class="`encounter-${group.status}`"><div><strong>{{ encounter.name }}</strong><small>{{ encounter.partyCharacterIds.length }} heroes · {{ encounter.opponents.reduce((sum,item)=>sum+item.quantity,0) }} creatures · {{ encounter.locked?'Locked':'Unlocked' }}</small></div><div class="saved-encounter-actions"><button type="button" class="secondary-button compact-action" :disabled="encounter.locked" @click="editEncounter(encounter)">Edit</button><button type="button" class="secondary-button compact-action" @click="updateEncounterLock(encounter,!encounter.locked)">{{ encounter.locked?'Unlock':'Lock' }}</button><button v-if="group.status!=='incomplete'" type="button" class="secondary-button compact-action" @click="updateEncounterApproval(encounter,group.status!=='approved')">{{ group.status==='approved'?'Remove Approval':'Approve' }}</button><button type="button" class="secondary-button compact-action" @click="duplicateEncounter(encounter)">Copy</button><button type="button" class="secondary-button compact-action danger" :disabled="encounter.locked||group.status==='approved'" @click="removeSavedEncounter(encounter)">Delete</button></div></article></div><p v-else class="muted">No {{ group.status }} encounters.</p></div></details></div><p v-else class="muted">No encounters saved yet.</p></section>
    </section>

    <section v-else class="character-sheet-view">
      <section v-if="selectedCharacter" class="digital-character-sheet card-surface review-character-sheet">
        <details class="review-section review-collapsible character-detail-section" open><summary><h2>Character Detail</h2><span>Identity &amp; origin</span></summary><div class="review-collapsible-body character-detail-body"><div class="field-grid two review-identity-edit"><label class="field-label review-name-field">Character Name<div class="field-control disabled-readout">{{ selectedCharacter.name }}</div></label><label class="field-label review-name-field">Campaign<div class="field-control disabled-readout">{{ selectedCharacter.campaignName||'No Campaign' }}</div></label></div><div class="review-grid review-summary-grid character-detail-summary-grid"><article><span>Species</span><strong>{{ selectedCharacter.species||'Not selected' }} <small v-if="isCustomSpecies(selectedCharacter.species)" class="custom-content-badge">CUSTOM</small></strong><small>{{ selectedCharacter.languages?.[0]||'—' }}</small></article><article><span>Spark</span><strong>{{ selectedCharacter.spark||'—' }}</strong></article><article><span>Homeland</span><strong>{{ selectedCharacter.homeland||'—' }}</strong></article><article><span>Oath</span><strong>{{ selectedCharacter.oath||'—' }}</strong></article><article><span>Faith</span><strong>{{ selectedCharacter.faith||'—' }}</strong></article><article><span>Path</span><strong>{{ selectedPathName }}</strong></article><article class="character-language-card"><span>Languages</span><strong>{{ selectedCharacter.languages?.join(' · ')||'—' }}</strong></article><article class="character-threat-card"><span>Threat Level · Point</span><strong>TL {{ selectedThreatLevel }} · {{ selectedThreat?.total||0 }} {{ (selectedThreat?.total||0)===1?'Point':'Points' }}</strong></article></div><section class="character-health-panel"><header><div><span>Health</span><strong>{{ selectedCharacter.currentHealth??CHARACTER_MAX_HEALTH }} / {{ CHARACTER_MAX_HEALTH }}</strong></div><span class="health-status-label" :class="`health-${selectedHealthState.label.toLowerCase().replace(/\s+/g,'-')}`">{{ selectedHealthState.label }}<template v-if="selectedHealthState.condition"> · {{ selectedHealthState.condition }}</template></span></header><div class="character-health-grid"><button v-for="cell in CHARACTER_MAX_HEALTH" :key="cell" type="button" :class="{filled:cell<=(selectedCharacter.currentHealth??CHARACTER_MAX_HEALTH),'health-last-breath':cell<=2,'health-critical':cell>2&&cell<=4,'health-wounded':cell>4&&cell<=8}" :aria-label="`Set Health to ${cell}`" @click="setCharacterHealth(cell)"></button></div><div class="health-controls"><button type="button" class="secondary-button compact-action" @click="setCharacterHealth((selectedCharacter.currentHealth??CHARACTER_MAX_HEALTH)-1)">−1</button><span>Low Health automatically applies its Condition to Dice Roller rolls for this selected character.</span><button type="button" class="secondary-button compact-action" @click="setCharacterHealth((selectedCharacter.currentHealth??CHARACTER_MAX_HEALTH)+1)">+1</button></div></section></div></details>
        <details class="review-section review-collapsible character-sheet-attributes" open><summary><h2>Attributes</h2><span>Ranks &amp; secondary stats</span></summary><div class="review-collapsible-body"><CharacterAttributePanel v-if="secondaryStats" :attributes="selectedCharacter.attributes" :magic-level="magicLevel" :guts-bonus="gearGutsBonus" :control-bonus="gearControlBonus" :magic-regen-bonus="gearMagicRegenBonus" :armor-penalty="gearSpeedPenalty" :minimum-speed="minimumSpeed" /></div></details>
        <details class="review-section review-collapsible review-weapons-section" open><summary><h2>Weapons</h2><span>{{ weapons.length }} equipped</span></summary><div class="review-collapsible-body equipment-slot-sheet"><div class="equipment-slot-header weapon-slot-grid"><span>Weapon</span><span>Damage</span><span>Range</span><span>Properties / Notes</span><span>Wt.</span></div><div v-for="(slot,index) in weaponSlots" :key="`weapon-slot-${index}`" class="equipment-slot-row weapon-slot-grid"><strong>{{ slot.name }}</strong><span>{{ slot.damage }}</span><span>{{ slot.range }}</span><span class="keyword-pill-row equipment-quality-cell"><span v-for="property in weaponPropertyPills(slot.properties)" :key="property" class="keyword-pill">{{ property }}</span><span v-if="!weaponPropertyPills(slot.properties).length">—</span></span><span>{{ slot.weight }}</span></div></div></details>
        <details class="review-section review-collapsible review-armor-section" open><summary><h2>Armor &amp; Shield</h2><span>{{ armor.length }} / 2 protective slots</span></summary><div class="review-collapsible-body"><div class="equipment-slot-sheet"><div class="equipment-slot-header armor-slot-grid"><span>Armor / Shield</span><span>Guts</span><span>Mana Syphon</span><span>Armor Penalty</span><span>Might</span><span>Wt.</span></div><div v-for="(slot,index) in armorSlots" :key="`armor-slot-${index}`" class="equipment-slot-row armor-slot-grid"><strong>{{ slot.name }}</strong><span>{{ slot.guts }}</span><span>{{ slot.mana }}</span><span>{{ slot.armorPenalty }}</span><span>{{ slot.might }}</span><span>{{ slot.weight }}</span></div></div><div class="trinket-slot-sheet"><h3>Trinkets</h3><div v-if="equippedTrinkets.length" class="trinket-slot-grid"><article v-for="(item,index) in equippedTrinkets" :key="`${item.name}-${index}`" class="trinket-slot-card"><strong>{{ item.name }}</strong><small>{{ item.effect || item.detail || 'Passive trinket effect.' }}</small></article></div><p v-else class="muted">No trinkets equipped.</p></div></div></details>
        <details class="review-section review-collapsible character-sheet-content-section"><summary><h2>Skills</h2><span>{{ selectedSkills.length }} recorded</span></summary><div class="review-collapsible-body"><div v-if="selectedSkills.length" class="review-skill-grid"><article v-for="skill in selectedSkills" :key="skill.name" class="review-skill-sheet-row" :class="skillToneClass(skill.name)"><div><strong>{{ skill.name }}</strong></div><div class="review-skill-values"><strong>Rank {{ skill.rank }}</strong><small>Modifier +{{ skillModifier(skill.rank) }}</small></div></article></div><p v-else class="muted">No Skills recorded.</p></div></details>
        <details v-if="magicLevel>0" class="review-section review-collapsible character-sheet-content-section"><summary><h2>Magic</h2><span>{{ selectedCharacter.loreAttunement||'Not selected' }} · {{ maxMana }} Mana Pool</span></summary><div class="review-collapsible-body"><article class="review-feature-box lore"><strong>Lore of {{ selectedCharacter.loreAttunement||'—' }}</strong><span>{{ loreDescriptions[selectedCharacter.loreAttunement||'']||'No Lore selected.' }}</span></article><h3 class="review-subheading">Lore Spells</h3><div class="review-spell-column"><article v-for="spell in loreCharacterSpells" :key="spell" class="review-feature-box spell full-rule-entry" :class="spellLoreClass(spell)"><header><strong>{{ spell }} <small v-if="isCustomSpell(spell)" class="custom-content-badge">CUSTOM</small></strong><small>{{ spellCostText(spell) }}</small></header><div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(spellDetail(spell)?.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div><span>{{ spell===signatureSpell?'Signature Spell · ':'' }}{{ spellDetail(spell)?.lore }}</span><p v-if="spellDetail(spell)?.flavor" class="rule-flavor"><em>{{ spellDetail(spell)?.flavor }}</em></p><div v-if="visibleRuleFields(spellRulesForCharacter(spell)).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(spellRulesForCharacter(spell))" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div></article><p v-if="!loreCharacterSpells.length" class="muted">No Lore Spells recorded.</p></div><h3 class="review-subheading">Invocation Spells</h3><div class="review-spell-column"><article v-for="spell in invocationCharacterSpells" :key="spell" class="review-feature-box spell full-rule-entry" :class="spellLoreClass(spell)"><header><strong>{{ spell }} <small v-if="isCustomSpell(spell)" class="custom-content-badge">CUSTOM</small></strong><small>{{ spellCostText(spell) }}</small></header><div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(spellDetail(spell)?.keywords)" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div><span>{{ spellDetail(spell)?.lore }}</span><p v-if="spellDetail(spell)?.flavor" class="rule-flavor"><em>{{ spellDetail(spell)?.flavor }}</em></p><div v-if="visibleRuleFields(spellRulesForCharacter(spell)).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(spellRulesForCharacter(spell))" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div></article><p v-if="!invocationCharacterSpells.length" class="muted">No Invocation Spells recorded.</p></div></div></details>
        <details class="review-section review-collapsible character-sheet-content-section"><summary><h2>Talents</h2><span>{{ selectedCharacter.talents?.length||0 }} selected</span></summary><div class="review-collapsible-body review-box-list review-talent-column"><article v-for="talent in selectedCharacter.talents||[]" :key="talent" class="review-feature-box talent full-rule-entry" :class="talentAbilityClasses(talent)"><header><strong>{{ canonicalTalentName(talent) }} <small v-if="isCustomTalent(talent)" class="custom-content-badge">CUSTOM</small></strong></header><div class="keyword-pill-row"><span v-for="keyword in abilityFeaturePillKeywords(talentKeywords(talent))" :key="keyword" :class="abilityFeaturePillClass(keyword)">{{ abilityFeaturePillLabel(keyword) }}</span></div><p v-if="structuredRule(talentText(talent)).intro" class="rule-flavor"><em>{{ structuredRule(talentText(talent)).intro }}</em></p><div v-if="visibleRuleFields(talentText(talent)).length" class="rule-breakdown-grid"><div v-for="field in visibleRuleFields(talentText(talent))" :key="field.label"><small>{{ field.label }}</small><span>{{ field.value }}</span></div></div></article><p v-if="!selectedCharacter.talents?.length">No Talents selected.</p></div></details>
